from pgmpy.causal_discovery import PC
import pandas as pd, numpy as np
from itertools import permutations

np.random.seed(42)

def fake_ci_t(X, Y, Z=[], **kwargs):
    Z = list(Z)
    # 4-cycle: A-C removed when condition on {B,D}; B-D removed when condition on {A,C}.
    if sorted([X, Y]) == ['A', 'C']:
        return set(Z) == {'B', 'D'}
    if sorted([X, Y]) == ['B', 'D']:
        return set(Z) == {'A', 'C'}
    return False

# iterate column permutations to see if edge removal order matters for either variant
results = {}
for cols in permutations(['A','B','C','D']):
    fake_data = pd.DataFrame(np.random.random((1000, 4)), columns=list(cols))
    for v in ["orig", "stable"]:
        skel, sep = PC()._build_skeleton(fake_data, ci_test=fake_ci_t, variant=v, show_progress=False, max_cond_vars=2)
        edges = frozenset((min(a,b), max(a,b)) for a,b in skel.edges())
        results.setdefault(v, set()).add(edges)

for v, edge_sets in results.items():
    print(v, len(edge_sets), [sorted(es) for es in edge_sets])
PY

