cd /testbed && /opt/conda/envs/testbed/bin/python - <<'PY'
from pgmpy.estimators import PC as OldPC
import pandas as pd, numpy as np
from itertools import permutations

np.random.seed(42)

def fake_ci_t(X, Y, Z=[], **kwargs):
    Z = list(Z)
    if len(Z) != 1:
        return False
    if sorted([X,Y]) == ['A','C']:
        return Z == ['D']
    if sorted([X,Y]) == ['B','C']:
        return Z == ['D']
    if sorted([X,Y]) == ['A','B']:
        return Z == ['C']
    return False

results = {}
for cols in permutations(['A','B','C','D','E']):
    fake_data = pd.DataFrame(np.random.random((1000, 5)), columns=list(cols))
    for v in ["orig", "stable"]:
        est = OldPC(fake_data)
        skel, sep = est.build_skeleton(ci_test=fake_ci_t, variant=v, show_progress=False, max_cond_vars=1)
        edges = frozenset((min(a,b), max(a,b)) for a,b in skel.edges())
        results.setdefault(v, set()).add(edges)

for v, edge_sets in results.items():
    print(v, len(edge_sets), [sorted(es) for es in edge_sets])
PY

